144:     public TypeSerializer<T> restoreSerializer() {
145:         final int numFields = snapshotData.getFieldSerializerSnapshots().size();
146: 
147:         final ArrayList<Field> restoredFields = new ArrayList<>(numFields);
148:         final ArrayList<TypeSerializer<?>> restoredFieldSerializers = new ArrayList<>(numFields);
149:         snapshotData
150:                 .getFieldSerializerSnapshots()
151:                 .forEach(
152:                         (fieldName, field, fieldSerializerSnapshot) -> {
153:                             restoredFields.add(field);
154:                             checkState(
155:                                     fieldSerializerSnapshot != null,
156:                                     "field serializer snapshots should be present.");
157:                             restoredFieldSerializers.add(
158:                                     fieldSerializerSnapshot.restoreSerializer());
159:                         });
160: 
161:         final LinkedHashMap<Class<?>, TypeSerializer<?>> registeredSubclassSerializers =
162:                 restoreSerializers(
163:                         snapshotData.getRegisteredSubclassSerializerSnapshots().unwrapOptionals());
164:         final Tuple2<LinkedHashMap<Class<?>, Integer>, TypeSerializer<Object>[]>
165:                 decomposedSubclassSerializerRegistry =
166:                         decomposeSubclassSerializerRegistry(registeredSubclassSerializers);
167: 
168:         final LinkedHashMap<Class<?>, TypeSerializer<?>> nonRegisteredSubclassSerializers =
169:                 restoreSerializers(
170:                         snapshotData
171:                                 .getNonRegisteredSubclassSerializerSnapshots()
172:                                 .unwrapOptionals());
