175:                 snapshotData.getPojoClass(),
176:                 restoredFields.toArray(new Field[numFields]),
177:                 restoredFieldSerializers.toArray(new TypeSerializer[numFields]),
178:                 decomposedSubclassSerializerRegistry.f0,
179:                 decomposedSubclassSerializerRegistry.f1,
180:                 nonRegisteredSubclassSerializers,
181:                 new ExecutionConfig());
