751:     /** Extracts the subclasses of the base POJO class registered in the execution config. */
752:     private static LinkedHashSet<Class<?>> getRegisteredSubclassesFromExecutionConfig(
753:             Class<?> basePojoClass, ExecutionConfig executionConfig) {
754: 
755:         LinkedHashSet<Class<?>> subclassesInRegistrationOrder =
756:                 CollectionUtil.newLinkedHashSetWithExpectedSize(
757:                         executionConfig.getRegisteredPojoTypes().size());
758:         for (Class<?> registeredClass : executionConfig.getRegisteredPojoTypes()) {
759:             if (registeredClass.equals(basePojoClass)) {
760:                 continue;
761:             }
762:             if (!basePojoClass.isAssignableFrom(registeredClass)) {
763:                 continue;
764:             }
765:             subclassesInRegistrationOrder.add(registeredClass);
766:         }
767: 
768:         return subclassesInRegistrationOrder;
769:     }
