775:     private static LinkedHashMap<Class<?>, Integer> createRegisteredSubclassTags(
776:             LinkedHashSet<Class<?>> registeredSubclasses) {
777:         final LinkedHashMap<Class<?>, Integer> classToTag = new LinkedHashMap<>();
778: 
779:         int id = 0;
780:         for (Class<?> registeredClass : registeredSubclasses) {
781:             classToTag.put(registeredClass, id);
782:             id++;
783:         }
