858:     /**
859:      * Build and return a snapshot of the serializer's parameters and currently cached serializers.
860:      */
861:     private static <T> PojoSerializerSnapshot<T> buildSnapshot(
862:             Class<T> pojoType,
863:             LinkedHashMap<Class<?>, Integer> registeredSubclassesToTags,
864:             TypeSerializer<?>[] registeredSubclassSerializers,
865:             Field[] fields,
866:             TypeSerializer<?>[] fieldSerializers,
867:             Map<Class<?>, TypeSerializer<?>> nonRegisteredSubclassSerializerCache,
868:             ExecutionConfig executionConfig) {
869: 
870:         final LinkedHashMap<Class<?>, TypeSerializer<?>> subclassRegistry =
871:                 CollectionUtil.newLinkedHashMapWithExpectedSize(registeredSubclassesToTags.size());
872: 
873:         for (Map.Entry<Class<?>, Integer> entry : registeredSubclassesToTags.entrySet()) {
874:             subclassRegistry.put(entry.getKey(), registeredSubclassSerializers[entry.getValue()]);
875:         }
876: 
877:         return new PojoSerializerSnapshot<>(
878:                 pojoType,
879:                 fields,
880:                 fieldSerializers,
881:                 subclassRegistry,
882:                 nonRegisteredSubclassSerializerCache,
883:                 executionConfig);
