48: public class ClearJoinHintsWithInvalidPropagationShuttle extends JoinHintsRelShuttle {
49: 
50:     @Override
51:     protected RelNode visitBiRel(BiRel biRel) {
52:         List<RelHint> hints = ((Hintable) biRel).getHints();
53: 
54:         Set<String> allHintNames =
55:                 hints.stream().map(hint -> hint.hintName).collect(Collectors.toSet());
56: 
57:         // there are no join hints on this Join/Correlate node
58:         if (allHintNames.stream().noneMatch(JoinStrategy::isJoinStrategy)) {
59:             return super.visit(biRel);
60:         }
61: 
62:         Optional<RelHint> firstAliasHint =
63:                 hints.stream()
64:                         .filter(hint -> FlinkHints.HINT_ALIAS.equals(hint.hintName))
65:                         .findFirst();
66: 
67:         // there are no alias hints on this Join/Correlate node
68:         if (!firstAliasHint.isPresent()) {
69:             return super.visit(biRel);
70:         }
71: 
72:         List<RelHint> joinHintsFromOuterQueryBlock =
73:                 hints.stream()
74:                         .filter(
75:                                 hint ->
76:                                         JoinStrategy.isJoinStrategy(hint.hintName)
77:                                                 // if the size of inheritPath is bigger than 0, it
78:                                                 // means that this join hint is propagated from its
79:                                                 // parent
80:                                                 && hint.inheritPath.size()
81:                                                         > firstAliasHint.get().inheritPath.size())
82:                         .collect(Collectors.toList());
83: 
84:         if (joinHintsFromOuterQueryBlock.isEmpty()) {
85:             return super.visit(biRel);
86:         }
87: 
88:         RelNode newJoin = biRel;
89:         ClearOuterJoinHintShuttle clearOuterJoinHintShuttle;
90: 
91:         for (RelHint outerJoinHint : joinHintsFromOuterQueryBlock) {
92:             clearOuterJoinHintShuttle = new ClearOuterJoinHintShuttle(outerJoinHint);
93:             newJoin = newJoin.accept(clearOuterJoinHintShuttle);
94:         }
95: 
96:         return super.visit(newJoin);
97:     }
