99:     /**
100:      * A shuttle to clean the join hints which are in outer query block and should not affect the
101:      * query-block inside.
102:      */
103:     private static class ClearOuterJoinHintShuttle extends RelShuttleImpl {
104:         // the current inheritPath about the join hint that need be removed
105:         private final Deque<Integer> currentInheritPath;
106: 
107:         // the join hint that need be removed
108:         private final RelHint joinHintNeedRemove;
109: 
110:         public ClearOuterJoinHintShuttle(RelHint joinHintNeedRemove) {
111:             this.joinHintNeedRemove = joinHintNeedRemove;
112:             this.currentInheritPath = new ArrayDeque<>();
113:             this.currentInheritPath.addAll(joinHintNeedRemove.inheritPath);
114:         }
115: 
116:         @Override
117:         protected RelNode visitChild(RelNode parent, int i, RelNode child) {
118:             currentInheritPath.addLast(i);
119:             RelNode newNode = super.visitChild(parent, i, child);
120:             currentInheritPath.removeLast();
121:             return newNode;
122:         }
123: 
124:         @Override
125:         public RelNode visit(LogicalCorrelate correlate) {
126:             return visitBiRel(correlate);
127:         }
128: 
129:         @Override
130:         public RelNode visit(LogicalJoin join) {
131:             return visitBiRel(join);
132:         }
133: 
134:         private RelNode visitBiRel(BiRel biRel) {
135:             Hintable hBiRel = (Hintable) biRel;
136:             List<RelHint> hints = new ArrayList<>(hBiRel.getHints());
137:             Optional<RelHint> invalidJoinHint = getInvalidJoinHint(hints);
138: 
139:             // if this join node contains the join hint that needs to be removed
140:             if (invalidJoinHint.isPresent()) {
141:                 hints.remove(invalidJoinHint.get());
142:                 return super.visit(hBiRel.withHints(hints));
143:             }
144: 
145:             return super.visit(biRel);
146:         }
