148:         /**
149:          * Get the invalid join hint in this node.
150:          *
151:          * <p>The invalid join meets the following requirement:
152:          *
153:          * <p>1. This hint name is same with the join hint that needs to be removed
154:          *
155:          * <p>2.The length of this hint should be same with the length of propagating this removed
156:          * join hint.
157:          *
158:          * <p>3. The inherited path of this hint should match the inherited path of this removed
159:          * join hint.
160:          *
161:          * @param hints all hints
162:          * @return return the invalid join hint if exists, else return empty
163:          */
164:         private Optional<RelHint> getInvalidJoinHint(List<RelHint> hints) {
165:             for (RelHint hint : hints) {
166:                 if (hint.hintName.equals(joinHintNeedRemove.hintName)
167:                         && isMatchInvalidInheritPath(
168:                                 new ArrayList<>(currentInheritPath), hint.inheritPath)) {
169:                     return Optional.of(hint);
170:                 }
171:             }
172:             return Optional.empty();
173:         }
174: 
175:         private boolean isMatchInvalidInheritPath(
176:                 List<Integer> invalidInheritPath, List<Integer> checkedInheritPath) {
177:             if (invalidInheritPath.size() != checkedInheritPath.size()) {
178:                 return false;
179:             }
180: 
181:             for (int i = 0; i < invalidInheritPath.size(); i++) {
182:                 if (!Objects.equals(invalidInheritPath.get(i), checkedInheritPath.get(i))) {
183:                     return false;
184:                 }
185:             }
186:             return true;
187:         }
188:     }
