35: /**
36:  * Clear the invalid join hints in the unmatched nodes. For example, a join hint may be attached in
37:  * the Project node at first. After accepting this shuttle, the join hint in the Project node will
38:  * be cleared.
39:  *
40:  * <p>See more at {@link FlinkHintStrategies}.
41:  *
42:  * <p>Tips, hints about view and alias will not be cleared.
43:  */
44: public class ClearJoinHintsOnUnmatchedNodesShuttle extends RelHomogeneousShuttle {
45:     private final HintStrategyTable hintStrategyTable;
46: 
47:     public ClearJoinHintsOnUnmatchedNodesShuttle(HintStrategyTable hintStrategyTable) {
48:         this.hintStrategyTable = hintStrategyTable;
49:     }
50: 
51:     @Override
52:     public RelNode visit(RelNode other) {
53:         if (FlinkRelOptUtil.containsSubQuery(other)) {
54:             other = resolveSubQuery(other, relNode -> relNode.accept(this));
55:         }
56: 
57:         if (other instanceof Hintable) {
58:             List<RelHint> originHints = ((Hintable) other).getHints();
59:             // 1. classify the hints and separate out the join hints
60:             List<RelHint> joinHints =
61:                     originHints.stream()
62:                             .filter(h -> JoinStrategy.isJoinStrategy(h.hintName))
63:                             .collect(Collectors.toList());
64: 
65:             List<RelHint> remainHints = new ArrayList<>(originHints);
66:             remainHints.removeAll(joinHints);
67: 
68:             // 2. use hintStrategyTable#apply to determine whether the join hint can be attached
69:             // to the current node
70:             // If it cannot be attached, it means that the join hint on the current node needs to
71:             // be removed.
72:             List<RelHint> hintsCanApply = hintStrategyTable.apply(joinHints, other);
73:             if (hintsCanApply.size() != joinHints.size()) {
74:                 hintsCanApply.addAll(remainHints);
75:                 // As a result, the remaining hints will be attached.
76:                 other = ((Hintable) other).withHints(hintsCanApply);
77:             }
78:         }
79: 
80:         return super.visit(other);
81:     }
82: }
