603:                     TestingCheckpointIDCounter.createStoreWithShutdownCheckAndNoStartAction(
604:                             checkpointIDCounterShutDownFuture));
605:         }
606: 
607:         public HaltingCheckpointRecoveryFactory(
608:                 CompletedCheckpointStore completedCheckpointStore,
609:                 CheckpointIDCounter checkpointIDCounter) {
610:             this.completedCheckpointStore = Preconditions.checkNotNull(completedCheckpointStore);
611:             this.checkpointIDCounter = Preconditions.checkNotNull(checkpointIDCounter);
612:         }
613: 
614:         @Override
615:         public CompletedCheckpointStore createRecoveredCompletedCheckpointStore(
616:                 JobID jobId,
617:                 int maxNumberOfCheckpointsToRetain,
618:                 SharedStateRegistryFactory sharedStateRegistryFactory,
619:                 Executor ioExecutor,
620:                 RestoreMode recoveryClaimMode)
621:                 throws Exception {
622:             creationLatch.await();
623:             return completedCheckpointStore;
624:         }
625: 
626:         @Override
627:         public CheckpointIDCounter createCheckpointIDCounter(JobID jobId) throws Exception {
628:             creationLatch.await();
629:             return checkpointIDCounter;
630:         }
