326:                 } catch (IOException e) {
327:                     // Sometimes it may happen that the files are being deleted while we list them,
328:                     // thus an IOException is raised.
329:                 }
330:                 if (fileExist) {
331:                     // We wait
332:                     Thread.sleep(500L);
333:                     waited += 500L;
334:                     // Or timeout
335:                     if (waited >= DELETE_TIMEOUT_MILLS) {
336:                         assertThat(fs.exists(checkpointDir)).isFalse();
337:                         assertThat(fs.listStatus(sharedFile)).isNullOrEmpty();
338:                         assertThat(fs.listStatus(taskOwnedFile)).isNullOrEmpty();
339:                     }
340:                 }
341:             }
342:         }
