246:     private void verifyStateHandleType(CheckpointMetadata metadata, boolean fileMergingEnabled)
247:             throws IOException {
248:         boolean hasKeyedState = false;
249:         for (OperatorState operatorState : metadata.getOperatorStates()) {
250:             for (OperatorSubtaskState subtaskState : operatorState.getStates()) {
251:                 // Check keyed state handle
252:                 List<KeyedStateHandle> keyedStateHandles =
253:                         new ArrayList<>(subtaskState.getManagedKeyedState());
254:                 for (KeyedStateHandle keyedStateHandle : keyedStateHandles) {
255:                     assertThat(keyedStateHandle)
256:                             .isInstanceOf(IncrementalRemoteKeyedStateHandle.class);
257:                     ((IncrementalRemoteKeyedStateHandle) keyedStateHandle)
258:                             .streamSubHandles()
259:                             .forEach(
260:                                     handle -> {
261:                                         if (fileMergingEnabled) {
262:                                             assertThat(handle)
263:                                                     .isInstanceOf(SegmentFileStateHandle.class);
264:                                         } else {
265:                                             assertThat(handle)
266:                                                     .isNotInstanceOf(SegmentFileStateHandle.class);
267:                                         }
268:                                     });
269:                     hasKeyedState = true;
270:                 }
271:             }
272:         }
273:         assertThat(hasKeyedState).isTrue();
274:     }
