276:     private static TernaryBoolean determineFileExist(
277:             RestoreMode mode, boolean lastFileMergingEnabled, boolean thisFileMergingEnabled) {
278:         if (mode == RestoreMode.CLAIM) {
279:             if (lastFileMergingEnabled || thisFileMergingEnabled) {
280:                 // file merging will not reference files from previous jobs.
281:                 return TernaryBoolean.FALSE;
282:             } else {
283:                 return TernaryBoolean.UNDEFINED;
284:             }
285:         } else {
286:             return TernaryBoolean.TRUE;
287:         }
288:     }
