399:     private static String runJobAndGetExternalizedCheckpoint(
400:             StateBackend backend,
401:             @Nullable String externalCheckpoint,
402:             MiniClusterWithClientResource cluster,
403:             RestoreMode restoreMode)
404:             throws Exception {
405:         // complete at least two checkpoints so that the initial checkpoint can be subsumed
406:         return runJobAndGetExternalizedCheckpoint(
407:                 backend, externalCheckpoint, cluster, restoreMode, new Configuration(), 2, true);
408:     }
409: 
410:     static String runJobAndGetExternalizedCheckpoint(
411:             StateBackend backend,
412:             @Nullable String externalCheckpoint,
413:             MiniClusterWithClientResource cluster,
414:             RestoreMode restoreMode,
415:             Configuration jobConfig,
416:             int consecutiveCheckpoints,
417:             boolean retainCheckpoints)
418:             throws Exception {
419:         JobGraph initialJobGraph =
420:                 getJobGraph(backend, externalCheckpoint, restoreMode, jobConfig, retainCheckpoints);
421:         NotifyingInfiniteTupleSource.countDownLatch = new CountDownLatch(PARALLELISM);
422:         cluster.getClusterClient().submitJob(initialJobGraph).get();
423: 
424:         // wait until all sources have been started
425:         NotifyingInfiniteTupleSource.countDownLatch.await();
426: 
427:         waitForCheckpoint(
428:                 initialJobGraph.getJobID(), cluster.getMiniCluster(), consecutiveCheckpoints);
429:         cluster.getClusterClient().cancel(initialJobGraph.getJobID()).get();
430:         waitUntilJobCanceled(initialJobGraph.getJobID(), cluster.getClusterClient());
431: 
432:         return getLatestCompletedCheckpointPath(
433:                         initialJobGraph.getJobID(), cluster.getMiniCluster())
434:                 .<IllegalStateException>orElseThrow(
435:                         () -> {
436:                             throw new IllegalStateException("Checkpoint not generated");
437:                         });
438:     }
439: 
440:     private static JobGraph getJobGraph(
441:             StateBackend backend,
442:             @Nullable String externalCheckpoint,
443:             RestoreMode restoreMode,
444:             Configuration jobConfig,
445:             boolean retainCheckpoints) {
446:         final StreamExecutionEnvironment env =
447:                 StreamExecutionEnvironment.getExecutionEnvironment(jobConfig);
448: 
449:         env.enableCheckpointing(500);
450:         env.setStateBackend(backend);
451:         env.setParallelism(PARALLELISM);
452:         env.getCheckpointConfig()
453:                 .setExternalizedCheckpointRetention(
454:                         retainCheckpoints
455:                                 ? ExternalizedCheckpointRetention.RETAIN_ON_CANCELLATION
456:                                 : ExternalizedCheckpointRetention.DELETE_ON_CANCELLATION);
457:         env.setRestartStrategy(RestartStrategies.noRestart());
458: 
459:         env.addSource(new NotifyingInfiniteTupleSource(10_000))
460:                 .assignTimestampsAndWatermarks(IngestionTimeWatermarkStrategy.create())
461:                 .keyBy(0)
462:                 .window(TumblingEventTimeWindows.of(Time.seconds(3)))
463:                 .reduce((value1, value2) -> Tuple2.of(value1.f0, value1.f1 + value2.f1))
464:                 .filter(value -> value.f0.startsWith("Tuple 0"));
465: 
466:         StreamGraph streamGraph = env.getStreamGraph();
467: 
468:         JobGraph jobGraph = streamGraph.getJobGraph();
469: 
470:         // recover from previous iteration?
471:         if (externalCheckpoint != null) {
472:             jobGraph.setSavepointRestoreSettings(
473:                     SavepointRestoreSettings.forPath(externalCheckpoint, false, restoreMode));
474:         }
475: 
476:         return jobGraph;
477:     }
