399:     private static String runJobAndGetExternalizedCheckpoint(
400:             StateBackend backend,
401:             @Nullable String externalCheckpoint,
402:             MiniClusterWithClientResource cluster,
403:             RestoreMode recoveryClaimMode)
404:             throws Exception {
405:         // complete at least two checkpoints so that the initial checkpoint can be subsumed
406:         return runJobAndGetExternalizedCheckpoint(
407:                 backend, externalCheckpoint, cluster,
408:                 recoveryClaimMode, new Configuration(), 2, true);
409:     }
410: 
411:     static String runJobAndGetExternalizedCheckpoint(
412:             StateBackend backend,
413:             @Nullable String externalCheckpoint,
414:             MiniClusterWithClientResource cluster,
415:             RestoreMode recoveryClaimMode,
416:             Configuration jobConfig,
417:             int consecutiveCheckpoints,
418:             boolean retainCheckpoints)
419:             throws Exception {
420:         JobGraph initialJobGraph =
421:                 getJobGraph(backend, externalCheckpoint,
422:                         recoveryClaimMode, jobConfig, retainCheckpoints);
423:         NotifyingInfiniteTupleSource.countDownLatch = new CountDownLatch(PARALLELISM);
424:         cluster.getClusterClient().submitJob(initialJobGraph).get();
425: 
426:         // wait until all sources have been started
427:         NotifyingInfiniteTupleSource.countDownLatch.await();
428: 
429:         waitForCheckpoint(
430:                 initialJobGraph.getJobID(), cluster.getMiniCluster(), consecutiveCheckpoints);
431:         cluster.getClusterClient().cancel(initialJobGraph.getJobID()).get();
432:         waitUntilJobCanceled(initialJobGraph.getJobID(), cluster.getClusterClient());
433: 
434:         return getLatestCompletedCheckpointPath(
435:                         initialJobGraph.getJobID(), cluster.getMiniCluster())
436:                 .<IllegalStateException>orElseThrow(
437:                         () -> {
438:                             throw new IllegalStateException("Checkpoint not generated");
439:                         });
440:     }
441: 
442:     private static JobGraph getJobGraph(
443:             StateBackend backend,
444:             @Nullable String externalCheckpoint,
445:             RestoreMode restoreMode,
446:             Configuration jobConfig,
447:             boolean retainCheckpoints) {
448:         final StreamExecutionEnvironment env =
449:                 StreamExecutionEnvironment.getExecutionEnvironment(jobConfig);
450: 
451:         env.enableCheckpointing(500);
452:         env.setStateBackend(backend);
453:         env.setParallelism(PARALLELISM);
454:         env.getCheckpointConfig()
455:                 .setExternalizedCheckpointRetention(
456:                         retainCheckpoints
457:                                 ? ExternalizedCheckpointRetention.RETAIN_ON_CANCELLATION
458:                                 : ExternalizedCheckpointRetention.DELETE_ON_CANCELLATION);
459:         env.setRestartStrategy(RestartStrategies.noRestart());
460: 
461:         env.addSource(new NotifyingInfiniteTupleSource(10_000))
462:                 .assignTimestampsAndWatermarks(IngestionTimeWatermarkStrategy.create())
463:                 .keyBy(0)
464:                 .window(TumblingEventTimeWindows.of(Time.seconds(3)))
465:                 .reduce((value1, value2) -> Tuple2.of(value1.f0, value1.f1 + value2.f1))
466:                 .filter(value -> value.f0.startsWith("Tuple 0"));
467: 
468:         StreamGraph streamGraph = env.getStreamGraph();
469: 
470:         JobGraph jobGraph = streamGraph.getJobGraph();
471: 
472:         // recover from previous iteration?
473:         if (externalCheckpoint != null) {
474:             jobGraph.setSavepointRestoreSettings(
475:                     SavepointRestoreSettings.forPath(externalCheckpoint, false, restoreMode));
476:         }
477: 
478:         return jobGraph;
479:     }
