481:     /**
482:      * Infinite source which notifies when all of its sub tasks have been started via the count down
483:      * latch.
484:      */
485:     public static class NotifyingInfiniteTupleSource
486:             extends ManualWindowSpeedITCase.InfiniteTupleSource {
487: 
488:         private static final long serialVersionUID = 8120981235081181746L;
489: 
490:         private static CountDownLatch countDownLatch;
491: 
492:         public NotifyingInfiniteTupleSource(int numKeys) {
493:             super(numKeys);
494:         }
495: 
496:         @Override
497:         public void run(SourceContext<Tuple2<String, Integer>> out) throws Exception {
498:             if (countDownLatch != null) {
499:                 countDownLatch.countDown();
500:             }
501: 
502:             super.run(out);
503:         }
504:     }
505: 
506:     /**
507:      * This {@link WatermarkStrategy} assigns the current system time as the event-time timestamp.
508:      * In a real use case you should use proper timestamps and an appropriate {@link
509:      * WatermarkStrategy}.
510:      */
511:     private static class IngestionTimeWatermarkStrategy<T> implements WatermarkStrategy<T> {
512: 
513:         private IngestionTimeWatermarkStrategy() {}
514: 
515:         public static <T> IngestionTimeWatermarkStrategy<T> create() {
516:             return new IngestionTimeWatermarkStrategy<>();
517:         }
518: 
519:         @Override
520:         public WatermarkGenerator<T> createWatermarkGenerator(
521:                 WatermarkGeneratorSupplier.Context context) {
522:             return new AscendingTimestampsWatermarks<>();
523:         }
524: 
525:         @Override
526:         public TimestampAssigner<T> createTimestampAssigner(
527:                 TimestampAssignerSupplier.Context context) {
528:             return (event, timestamp) -> System.currentTimeMillis();
529:         }
530:     }
531: }
