91:             ArrayDeque<CompletedCheckpoint> checkpoints,
92:             Executor ioExecutor,
93:             RestoreMode restoreMode) {
94:         super(sharedStateRegistryFactory.create(ioExecutor, checkpoints, restoreMode));
95:         checkArgument(maxNumberOfCheckpointsToRetain >= 1, "Must retain at least one checkpoint.");
96:         this.maxNumberOfCheckpointsToRetain = maxNumberOfCheckpointsToRetain;
97:         this.checkpoints = checkpoints;
