101:     @Nullable
102:     @Override
103:     public CompletedCheckpoint addCheckpointAndSubsumeOldestOne(
104:             CompletedCheckpoint checkpoint,
105:             CheckpointsCleaner checkpointsCleaner,
106:             Runnable postCleanup)
107:             throws Exception {
108: 
109:         checkpoints.addLast(checkpoint);
110: 
111:         CompletedCheckpoint completedCheckpoint =
112:                 CheckpointSubsumeHelper.subsume(
113:                                 checkpoints,
114:                                 maxNumberOfCheckpointsToRetain,
115:                                 (cc) -> {
116:                                     cc.markAsDiscardedOnSubsume();
117:                                     checkpointsCleaner.addSubsumedCheckpoint(cc);
118:                                 })
119:                         .orElse(null);
120: 
121:         findLowest(checkpoints)
122:                 .ifPresent(
123:                         id ->
124:                                 checkpointsCleaner.cleanSubsumedCheckpoints(
125:                                         id,
126:                                         getSharedStateRegistry().unregisterUnusedState(id),
127:                                         postCleanup,
128:                                         ioExecutor));
129: 
130:         return completedCheckpoint;
131:     }
