150:             throws Exception {
151:         super.shutdown(jobStatus, checkpointsCleaner);
152:         try {
153:             LOG.info("Shutting down");
154: 
155:             long lowestRetained = Long.MAX_VALUE;
156:             for (CompletedCheckpoint checkpoint : checkpoints) {
157:                 if (checkpoint.shouldBeDiscardedOnShutdown(jobStatus)) {
158:                     checkpoint.markAsDiscardedOnShutdown(jobStatus).discard();
159:                 } else {
160:                     LOG.info(
161:                             "Checkpoint with ID {} at '{}' not discarded.",
162:                             checkpoint.getCheckpointID(),
163:                             checkpoint.getExternalPointer());
164:                     lowestRetained = Math.min(checkpoint.getCheckpointID(), lowestRetained);
165:                 }
166:             }
167:             if (jobStatus.isGloballyTerminalState()) {
168:                 // Now discard the shared state of not subsumed checkpoints - only if:
169:                 // - the job is in a globally terminal state. Otherwise,
170:                 // it can be a suspension, after which this state might still be needed.
171:                 // - checkpoint is not retained (it might be used externally)
172:                 // - checkpoint handle removal succeeded (e.g. from ZK) - otherwise, it might still
173:                 // be used in recovery if the job status is lost
174:                 checkpointsCleaner.cleanSubsumedCheckpoints(
175:                         lowestRetained,
176:                         getSharedStateRegistry().unregisterUnusedState(lowestRetained),
177:                         () -> {},
178:                         ioExecutor);
