212:     @Test
213:     public void testTriggerRescaleOnFailedCheckpoint() throws Exception {
214:         final AtomicInteger rescaleTriggerCount = new AtomicInteger();
215:         final StateTransitionManager.Factory rescaleManagerFactory =
216:                 new TestingStateTransitionManager.Factory(() -> {}, rescaleTriggerCount::incrementAndGet);
217:         final int rescaleOnFailedCheckpointsCount = 3;
218:         try (MockExecutingContext ctx = new MockExecutingContext()) {
219:             final Executing testInstance =
220:                     new ExecutingStateBuilder()
221:                             .setRescaleManagerFactory(rescaleManagerFactory)
222:                             .setRescaleOnFailedCheckpointCount(rescaleOnFailedCheckpointsCount)
223:                             .build(ctx);
224: 
225:             // do multiple rescale iterations to verify that subsequent failed checkpoints after a
226:             // rescale result in the expected behavior
227:             for (int rescaleIteration = 1; rescaleIteration <= 3; rescaleIteration++) {
228: 
229:                 // trigger an initial failed checkpoint event to show that the counting only starts
230:                 // with the subsequent change event
231:                 testInstance.onFailedCheckpoint();
232: 
233:                 // trigger change
234:                 testInstance.onNewResourceRequirements();
235: 
236:                 for (int i = 0; i < rescaleOnFailedCheckpointsCount; i++) {
237:                     assertThat(rescaleTriggerCount)
238:                             .as(
239:                                     "No rescale operation should have been triggered for iteration #%d, yet.",
240:                                     rescaleIteration)
241:                             .hasValue(rescaleIteration - 1);
242:                     testInstance.onFailedCheckpoint();
243:                 }
244: 
245:                 assertThat(rescaleTriggerCount)
246:                         .as(
247:                                 "The rescale operation for iteration #%d should have been properly triggered.",
248:                                 rescaleIteration)
249:                         .hasValue(rescaleIteration);
250:             }
251:         }
252:     }
