1430:     @Override
1431:     public FailureResult howToHandleFailure(
1432:             Throwable failure, CompletableFuture<Map<String, String>> failureLabels) {
1433:         FailureResult failureResult = howToHandleFailure(failure);
1434:         if (reportEventsAsSpans) {
1435:             // TODO: replace with reporting as event once events are supported.
1436:             // Add reporting as callback for when the failure labeling is completed.
1437:             failureLabels.thenAcceptAsync(
