238:     @Test
239:     void testBasicGetNextLogic() throws Exception {
240:         // Setup
241:         final SingleInputGate inputGate = createInputGate();
242: 
243:         final TestInputChannel[] inputChannels =
244:                 new TestInputChannel[] {
245:                     new TestInputChannel(inputGate, 0), new TestInputChannel(inputGate, 1)
246:                 };
247: 
248:         inputGate.setInputChannels(inputChannels);
249: 
250:         // Test
251:         inputChannels[0].readBuffer();
252:         inputChannels[0].readBuffer();
253:         inputChannels[1].readBuffer();
254:         inputChannels[1].readEndOfData();
255:         inputChannels[0].readEndOfData();
256:         inputChannels[1].readEndOfPartitionEvent();
257:         inputChannels[0].readEndOfPartitionEvent();
258: 
259:         inputGate.notifyChannelNonEmpty(inputChannels[0]);
260:         inputGate.notifyChannelNonEmpty(inputChannels[1]);
261: 
262:         verifyBufferOrEvent(inputGate, true, 0, true);
263:         verifyBufferOrEvent(inputGate, true, 1, true);
264:         verifyBufferOrEvent(inputGate, true, 0, true);
265:         verifyBufferOrEvent(inputGate, false, 1, true);
266:         // we have received EndOfData on a single channel only
267:         assertThat(inputGate.hasReceivedEndOfData())
268:                 .isEqualTo(PullingAsyncDataInput.EndOfDataStatus.NOT_END_OF_DATA);
269:         verifyBufferOrEvent(inputGate, false, 0, true);
270:         assertThat(inputGate.isFinished()).isFalse();
271:         assertThat(inputGate.hasReceivedEndOfData())
272:                 .isEqualTo(PullingAsyncDataInput.EndOfDataStatus.DRAINED);
273:         verifyBufferOrEvent(inputGate, false, 1, true);
274:         verifyBufferOrEvent(inputGate, false, 0, false);
275: 
276:         // Return null when the input gate has received all end-of-partition events
277:         assertThat(inputGate.hasReceivedEndOfData())
278:                 .isEqualTo(PullingAsyncDataInput.EndOfDataStatus.DRAINED);
279:         assertThat(inputGate.isFinished()).isTrue();
280: 
281:         for (TestInputChannel ic : inputChannels) {
282:             ic.assertReturnedEventsAreRecycled();
283:         }
284:     }
