1237:     private static void verifyBuffersInBufferPool(boolean isPipeline, int subpartitionRandSize)
1238:             throws Exception {
1239:         IntermediateResultPartitionID[] partitionIds =
1240:                 new IntermediateResultPartitionID[] {
1241:                     new IntermediateResultPartitionID(),
1242:                     new IntermediateResultPartitionID(),
1243:                     new IntermediateResultPartitionID()
1244:                 };
1245: 
1246:         IndexRange subpartitionIndexRange = new IndexRange(0, subpartitionRandSize - 1);
1247:         NettyShuffleEnvironmentBuilder nettyShuffleEnvironmentBuilder =
1248:                 new NettyShuffleEnvironmentBuilder();
1249:         Optional<Integer> expectMaxRequiredBuffersPerGate =
1250:                 isPipeline
1251:                         ? Optional.of(
1252:                                 InputGateSpecUtils.DEFAULT_MAX_REQUIRED_BUFFERS_PER_GATE_FOR_STREAM)
1253:                         : Optional.of(
1254:                                 InputGateSpecUtils.DEFAULT_MAX_REQUIRED_BUFFERS_PER_GATE_FOR_BATCH);
1255:         nettyShuffleEnvironmentBuilder.setMaxRequiredBuffersPerGate(
1256:                 expectMaxRequiredBuffersPerGate);
1257:         NettyShuffleEnvironment netEnv = nettyShuffleEnvironmentBuilder.build();
1258: 
1259:         SingleInputGate gate =
1260:                 createSingleInputGate(
1261:                         partitionIds,
1262:                         isPipeline ? ResultPartitionType.PIPELINED : ResultPartitionType.BLOCKING,
1263:                         subpartitionIndexRange,
1264:                         netEnv,
1265:                         ResourceID.generate(),
1266:                         new TestingConnectionManager(),
1267:                         new TestingResultPartitionManager(new NoOpResultSubpartitionView()));
1268:         gate.setup();
1269: 
1270:         for (InputChannel inputChannel : gate.inputChannels()) {
1271:             if (inputChannel instanceof RemoteInputChannel) {
1272:                 assertThat(((RemoteInputChannel) inputChannel).getInitialCredit()).isEqualTo(0);
1273:             }
1274:         }
1275: 
1276:         int maxBuffersPerGate = 2 * partitionIds.length * subpartitionRandSize + 8;
1277:         int minBuffersPerGate;
1278:         if (maxBuffersPerGate >= expectMaxRequiredBuffersPerGate.get()) {
1279:             minBuffersPerGate = expectMaxRequiredBuffersPerGate.get();
1280:         } else {
1281:             minBuffersPerGate = 2 * partitionIds.length * subpartitionRandSize + 1;
1282:         }
1283:         assertThat(gate.getBufferPool().getExpectedNumberOfMemorySegments())
1284:                 .isEqualTo(minBuffersPerGate);
1285:         assertThat(gate.getBufferPool().getMaxNumberOfMemorySegments())
1286:                 .isEqualTo(maxBuffersPerGate);
1287:     }
