676:     /** Tests request back off configuration is correctly forwarded to the channels. */
677:     @Test
678:     void testRequestBackoffConfiguration() throws Exception {
679:         IntermediateResultPartitionID[] partitionIds =
680:                 new IntermediateResultPartitionID[] {
681:                     new IntermediateResultPartitionID(),
682:                     new IntermediateResultPartitionID(),
683:                     new IntermediateResultPartitionID()
684:                 };
685: 
686:         int initialBackoff = 137;
687:         int partitionRequestTimeout = 600;
688:         int maxBackoff = 1001;
689: 
690:         final NettyShuffleEnvironment netEnv =
691:                 new NettyShuffleEnvironmentBuilder()
692:                         .setPartitionRequestInitialBackoff(initialBackoff)
693:                         .setPartitionRequestTimeout(partitionRequestTimeout)
694:                         .setPartitionRequestMaxBackoff(maxBackoff)
695:                         .build();
696: 
697:         SingleInputGate gate =
698:                 createSingleInputGate(partitionIds, ResultPartitionType.PIPELINED, netEnv);
699:         gate.setChannelStateWriter(ChannelStateWriter.NO_OP);
700: 
701:         gate.finishReadRecoveredState();
702:         while (!gate.getStateConsumedFuture().isDone()) {
703:             gate.pollNext();
704:         }
705:         gate.convertRecoveredInputChannels();
706: 
707:         try (Closer closer = Closer.create()) {
708:             closer.register(netEnv::close);
709:             closer.register(gate::close);
710: 
711:             assertThat(gate.getConsumedPartitionType()).isEqualTo(ResultPartitionType.PIPELINED);
712: 
713:             Map<Tuple2<IntermediateResultPartitionID, InputChannelInfo>, InputChannel> channelMap =
714:                     gate.getInputChannels();
715: 
716:             assertThat(channelMap.size()).isEqualTo(3);
717:             channelMap
718:                     .values()
719:                     .forEach(
720:                             channel -> {
721:                                 try {
722:                                     channel.checkError();
723:                                 } catch (IOException e) {
724:                                     throw new RuntimeException(e);
725:                                 }
726:                             });
727:             InputChannel localChannel = getTheOnlyInputChannelInPartition(gate, partitionIds[0]);
728:             assertThat(localChannel.getClass()).isEqualTo(LocalInputChannel.class);
729: 
730:             InputChannel unknownChannel = getTheOnlyInputChannelInPartition(gate, partitionIds[2]);
731:             assertThat(unknownChannel.getClass()).isEqualTo(UnknownInputChannel.class);
732: 
733:             InputChannel[] channels = new InputChannel[] {localChannel, unknownChannel};
734:             for (InputChannel ch : channels) {
735:                 assertThat(ch.getCurrentBackoff()).isEqualTo(0);
736: 
737:                 assertThat(ch.increaseBackoff()).isTrue();
738:                 assertThat(ch.getCurrentBackoff()).isEqualTo(initialBackoff);
739: 
740:                 assertThat(ch.increaseBackoff()).isTrue();
741:                 assertThat(ch.getCurrentBackoff()).isEqualTo(initialBackoff * 2);
742: 
743:                 assertThat(ch.increaseBackoff()).isTrue();
744:                 assertThat(ch.getCurrentBackoff()).isEqualTo(initialBackoff * 2 * 2);
745: 
746:                 assertThat(ch.increaseBackoff()).isTrue();
747:                 assertThat(ch.getCurrentBackoff()).isEqualTo(maxBackoff);
748: 
749:                 assertThat(ch.increaseBackoff()).isFalse();
750:             }
751: 
752:             InputChannel remoteChannel = getTheOnlyInputChannelInPartition(gate, partitionIds[1]);
753:             assertThat(remoteChannel.getClass()).isEqualTo(RemoteInputChannel.class);
754: 
755:             assertThat(remoteChannel.getCurrentBackoff()).isEqualTo(0);
756: 
757:             assertThat(remoteChannel.increaseBackoff()).isTrue();
758:             assertThat(remoteChannel.getCurrentBackoff()).isEqualTo(partitionRequestTimeout);
759: 
760:             assertThat(remoteChannel.increaseBackoff()).isTrue();
761:             assertThat(remoteChannel.getCurrentBackoff()).isEqualTo(partitionRequestTimeout * 2);
762: 
763:             assertThat(remoteChannel.increaseBackoff()).isTrue();
764:             assertThat(remoteChannel.getCurrentBackoff()).isEqualTo(partitionRequestTimeout * 3);
765: 
766:             assertThat(remoteChannel.increaseBackoff()).isFalse();
