1258: 
1259:         SingleInputGate gate =
1260:                 createSingleInputGate(
1261:                         partitionIds,
1262:                         isPipeline ? ResultPartitionType.PIPELINED : ResultPartitionType.BLOCKING,
1263:                         subpartitionIndexRange,
1264:                         netEnv,
1265:                         ResourceID.generate(),
1266:                         new TestingConnectionManager(),
1267:                         new TestingResultPartitionManager(new NoOpResultSubpartitionView()));
1268:         gate.setup();
