1270:         for (InputChannel inputChannel : gate.inputChannels()) {
1271:             if (inputChannel instanceof RemoteInputChannel) {
1272:                 assertThat(((RemoteInputChannel) inputChannel).getInitialCredit()).isEqualTo(0);
1273:             }
