773:     @Override
774:     public Map<String, OptionalFailure<Accumulator<?, ?>>> aggregateUserAccumulators() {
775: 
776:         Map<String, OptionalFailure<Accumulator<?, ?>>> userAccumulators = new HashMap<>();
777: 
778:         for (ExecutionVertex vertex : getAllExecutionVertices()) {
779:             Map<String, Accumulator<?, ?>> next =
780:                     vertex.getCurrentExecutionAttempt().getUserAccumulators();
781:             if (next != null) {
