881:     @Override
882:     public void addNewJobVertices(
883:             List<JobVertex> topologicallySortedNewlyJobVertices,
884:             JobManagerJobMetricGroup jobManagerJobMetricGroup,
885:             VertexParallelismStore newVerticesParallelismStore)
886:             throws JobException {
887:         // sanity check
888:         Set<JobVertexID> existingKeys = new HashSet<>(this.tasks.keySet());
889:         Set<JobVertexID> newKeys =
890:                 topologicallySortedNewlyJobVertices.stream()
891:                         .map(JobVertex::getID)
892:                         .collect(Collectors.toSet());
893:         newKeys.retainAll(existingKeys);
894:         if (!newKeys.isEmpty()) {
895:             throw new IllegalArgumentException(
896:                     "Unexpected JobVertices that have already been added: " + newKeys);
897:         }
898: 
899:         DefaultVertexParallelismStore vertexParallelismStore = new DefaultVertexParallelismStore();
900:         vertexParallelismStore.mergeParallelismStore(this.parallelismStore);
901:         vertexParallelismStore.mergeParallelismStore(newVerticesParallelismStore);
902:         this.parallelismStore = vertexParallelismStore;
903: 
904:         attachJobVertices(topologicallySortedNewlyJobVertices, jobManagerJobMetricGroup);
905: 
906:         List<JobVertex> topologicallySortedJobVertices =
907:                 IterableUtils.toStream(getVerticesTopologically())
908:                         .map(ExecutionJobVertex::getJobVertex)
909:                         .collect(Collectors.toList());
910:         executionTopology.notifyExecutionGraphUpdatedWithNewJobVertices(
911:                 topologicallySortedJobVertices);
912:     }
