1254:     private CompletableFuture<?> waitForAllExecutionsTermination() {
1255:         final List<CompletableFuture<?>> terminationFutures =
1256:                 verticesInCreationOrder.stream()
1257:                         .flatMap(ejv -> Arrays.stream(ejv.getTaskVertices()))
1258:                         .map(ExecutionVertex::getTerminationFuture)
1259:                         .collect(Collectors.toList());
1260: 
1261:         return FutureUtils.waitForAll(terminationFutures);
1262:     }
