1533:     @VisibleForTesting
1534:     public ResultPartitionID createResultPartitionId(
1535:             final IntermediateResultPartitionID resultPartitionId) {
1536:         final SchedulingResultPartition schedulingResultPartition =
1537:                 getSchedulingTopology().getResultPartition(resultPartitionId);
1538:         final SchedulingExecutionVertex producer = schedulingResultPartition.getProducer();
1539:         final ExecutionVertexID producerId = producer.getId();
1540:         final JobVertexID jobVertexId = producerId.getJobVertexId();
1541:         final ExecutionJobVertex jobVertex = getJobVertex(jobVertexId);
1542:         checkNotNull(jobVertex, "Unknown job vertex %s", jobVertexId);
1543: 
1544:         final ExecutionVertex[] taskVertices = jobVertex.getTaskVertices();
1545:         final int subtaskIndex = producerId.getSubtaskIndex();
1546:         checkState(
1547:                 subtaskIndex < taskVertices.length,
1548:                 "Invalid subtask index %d for job vertex %s",
1549:                 subtaskIndex,
1550:                 jobVertexId);
1551: 
1552:         final ExecutionVertex taskVertex = taskVertices[subtaskIndex];
1553:         final Execution execution = taskVertex.getCurrentExecutionAttempt();
1554:         return new ResultPartitionID(resultPartitionId, execution.getAttemptId());
1555:     }
