1002:     private boolean areJobVerticesAllInitialized(final SlotSharingGroup group) {
1003:         for (JobVertexID jobVertexId : group.getJobVertexIds()) {
1004:             final ExecutionJobVertex jobVertex = getJobVertex(jobVertexId);
1005:             checkNotNull(jobVertex, "Unknown job vertex %s", jobVertexId);
1006:             if (!jobVertex.isInitialized()) {
1007:                 return false;
1008:             }
1009:         }
1010:         return true;
1011:     }
