1195:     private boolean transitionState(JobStatus current, JobStatus newState, Throwable error) {
1196:         assertRunningInJobMasterMainThread();
1197:         // consistency check
1198:         if (current.isTerminalState()) {
1199:             String message = "Job is trying to leave terminal state " + current;
1200:             LOG.error(message);
1201:             throw new IllegalStateException(message);
1202:         }
1203: 
1204:         // now do the actual state transition
1205:         if (state == current) {
1206:             state = newState;
1207:             LOG.info(
1208:                     "Job {} ({}) switched from state {} to {}.",
1209:                     getJobName(),
1210:                     getJobID(),
1211:                     current,
1212:                     newState,
1213:                     error);
1214: 
1215:             stateTimestamps[newState.ordinal()] = System.currentTimeMillis();
1216:             notifyJobStatusChange(current, newState, error);
1217:             notifyJobStatusHooks(newState, error);
1218:             return true;
1219:         } else {
1220:             return false;
1221:         }
1222:     }
