1419:     @Override
1420:     public boolean updateState(TaskExecutionStateTransition state) {
1421:         assertRunningInJobMasterMainThread();
1422:         final Execution attempt = currentExecutions.get(state.getID());
1423: 
1424:         if (attempt != null) {
1425:             try {
1426:                 final boolean stateUpdated = updateStateInternal(state, attempt);
1427:                 maybeReleasePartitionGroupsFor(attempt);
1428:                 return stateUpdated;
1429:             } catch (Throwable t) {
1430:                 ExceptionUtils.rethrowIfFatalErrorOrOOM(t);
1431: 
1432:                 // failures during updates leave the ExecutionGraph inconsistent
1433:                 failGlobal(t);
1434:                 return false;
1435:             }
1436:         } else {
1437:             return false;
1438:         }
1439:     }
1440: 
1441:     private boolean updateStateInternal(
1442:             final TaskExecutionStateTransition state, final Execution attempt) {
1443:         Map<String, Accumulator<?, ?>> accumulators;
1444: 
1445:         switch (state.getExecutionState()) {
1446:             case INITIALIZING:
1447:                 return attempt.switchToInitializing();
1448: 
1449:             case RUNNING:
1450:                 if (!isAnyOutputBlocking(this)
1451:                         && checkpointCoordinator != null
1452:                         && checkpointCoordinator.isPeriodicCheckpointingConfigured()
1453:                         && !checkpointCoordinator.isPeriodicCheckpointingStarted()) {
1454:                     checkpointCoordinator.startCheckpointScheduler();
1455:                 }
1456: 
1457:                 return attempt.switchToRunning();
1458: 
1459:             case FINISHED:
1460:                 // this deserialization is exception-free
1461:                 accumulators = deserializeAccumulators(state);
1462:                 attempt.markFinished(accumulators, state.getIOMetrics());
1463:                 return true;
1464: 
1465:             case CANCELED:
1466:                 // this deserialization is exception-free
1467:                 accumulators = deserializeAccumulators(state);
1468:                 attempt.completeCancelling(accumulators, state.getIOMetrics(), false);
1469:                 return true;
1470: 
1471:             case FAILED:
1472:                 // this deserialization is exception-free
1473:                 accumulators = deserializeAccumulators(state);
1474:                 attempt.markFailed(
1475:                         state.getError(userClassLoader),
1476:                         state.getCancelTask(),
1477:                         accumulators,
1478:                         state.getIOMetrics(),
1479:                         state.getReleasePartitions(),
1480:                         true);
1481:                 return true;
1482: 
1483:             default:
1484:                 // we mark as failed and return false, which triggers the TaskManager
1485:                 // to remove the task
1486:                 attempt.fail(
1487:                         new Exception(
1488:                                 "TaskManager sent illegal state update: "
1489:                                         + state.getExecutionState()));
1490:                 return false;
1491:         }
1492:     }
