1659:                 try {
1660:                     listener.jobStatusChanges(getJobID(), newState, timestamp);
1661:                 } catch (Throwable t) {
1662:                     LOG.warn("Error while notifying JobStatusListener", t);
1663:                 }
1664:             }
1665:         }
1666: 
1667:         if (jobStatusChangedListeners.size() > 0) {
1668:             jobStatusChangedListeners.forEach(
1669:                     listener ->
