1676:     private void notifyJobStatusHooks(JobStatus newState, @Nullable Throwable cause) {
1677:         JobID jobID = jobInformation.getJobId();
1678:         for (JobStatusHook hook : jobStatusHooks) {
1679:             try {
1680:                 switch (newState) {
1681:                     case CREATED:
1682:                         hook.onCreated(jobID);
1683:                         break;
1684:                     case CANCELED:
1685:                         hook.onCanceled(jobID);
1686:                         break;
1687:                     case FAILED:
1688:                         hook.onFailed(jobID, cause);
1689:                         break;
1690:                     case FINISHED:
1691:                         hook.onFinished(jobID);
1692:                         break;
1693:                 }
1694:             } catch (Throwable e) {
1695:                 throw new RuntimeException(
1696:                         "Error while notifying JobStatusHook[" + hook.getClass() + "]", e);
1697:             }
1698:         }
1699:     }
