914:     /** Attach job vertices without initializing them. */
915:     private void attachJobVertices(
916:             List<JobVertex> topologicallySorted, JobManagerJobMetricGroup jobManagerJobMetricGroup)
917:             throws JobException {
918:         for (JobVertex jobVertex : topologicallySorted) {
919: 
920:             if (jobVertex.isInputVertex() && !jobVertex.isStoppable()) {
921:                 this.isStoppable = false;
922:             }
923: 
924:             VertexParallelismInformation parallelismInfo =
925:                     parallelismStore.getParallelismInfo(jobVertex.getID());
926: 
927:             // create the execution job vertex and attach it to the graph
928:             ExecutionJobVertex ejv =
929:                     executionJobVertexFactory.createExecutionJobVertex(
930:                             this,
931:                             jobVertex,
932:                             parallelismInfo,
933:                             coordinatorStore,
934:                             jobManagerJobMetricGroup);
935: 
936:             ExecutionJobVertex previousTask = this.tasks.putIfAbsent(jobVertex.getID(), ejv);
937:             if (previousTask != null) {
938:                 throw new JobException(
939:                         String.format(
940:                                 "Encountered two job vertices with ID %s : previous=[%s] / new=[%s]",
941:                                 jobVertex.getID(), ejv, previousTask));
942:             }
943: 
944:             this.verticesInCreationOrder.add(ejv);
945:             this.numJobVerticesTotal++;
946:         }
947:     }
