1083:     private CompletableFuture<Void> applyToVertexAsync(
1084:             Function<ExecutionJobVertex, CompletableFuture<Void>> perVertexOperationAsync) {
1085:         return FutureUtils.waitForAll(
1086:                 verticesInCreationOrder.stream()
1087:                         .map(perVertexOperationAsync)
1088:                         .collect(Collectors.toList()));
