1124:     void failGlobalIfExecutionIsStillRunning(Throwable cause, ExecutionAttemptID failingAttempt) {
1125:         final Execution failedExecution = currentExecutions.get(failingAttempt);
1126:         if (failedExecution != null
1127:                 && (failedExecution.getState() == ExecutionState.RUNNING
1128:                         || failedExecution.getState() == ExecutionState.INITIALIZING)) {
1129:             failGlobal(cause);
1130:         } else {
1131:             LOG.debug(
1132:                     "The failing attempt {} belongs to an already not"
1133:                             + " running task thus won't fail the job",
1134:                     failingAttempt);
1135:         }
1136:     }
