949:     private void initializeJobVertices(List<JobVertex> topologicallySorted) throws JobException {
950:         final long createTimestamp = System.currentTimeMillis();
951: 
952:         for (JobVertex jobVertex : topologicallySorted) {
953:             final ExecutionJobVertex ejv = tasks.get(jobVertex.getID());
954:             initializeJobVertex(ejv, createTimestamp);
955:         }
