1239:     /**
1240:      * Called whenever a job vertex reaches state FINISHED (completed successfully). Once all job
1241:      * vertices are in the FINISHED state, the program is successfully done.
1242:      */
1243:     @Override
1244:     public void jobVertexFinished() {
1245:         assertRunningInJobMasterMainThread();
1246:         final int numFinished = ++numFinishedJobVertices;
1247:         if (numFinished == numJobVerticesTotal
1248:                 && executionPlanSchedulingContext.getPendingOperatorCount() == 0) {
