1329:     /**
1330:      * This method is a callback during cancellation/failover and called when all tasks have reached
1331:      * a terminal state (cancelled/failed/finished).
1332:      */
1333:     private void allVerticesInTerminalState() {
1334: 
1335:         assertRunningInJobMasterMainThread();
1336: 
1337:         // we are done, transition to the final state
1338:         JobStatus current;
1339:         while (true) {
1340:             current = this.state;
1341: 
1342:             if (current == JobStatus.RUNNING) {
1343:                 failGlobal(
1344:                         new Exception(
1345:                                 "ExecutionGraph went into allVerticesInTerminalState() from RUNNING"));
1346:             } else if (current == JobStatus.CANCELLING) {
1347:                 if (transitionState(current, JobStatus.CANCELED)) {
1348:                     onTerminalState(JobStatus.CANCELED);
1349:                     break;
1350:                 }
1351:             } else if (current == JobStatus.FAILING) {
1352:                 break;
1353:             } else if (current.isGloballyTerminalState()) {
1354:                 LOG.warn(
1355:                         "Job has entered globally terminal state without waiting for all "
1356:                                 + "job vertices to reach final state.");
1357:                 break;
1358:             } else {
1359:                 failGlobal(
1360:                         new Exception(
1361:                                 "ExecutionGraph went into final state from state " + current));
1362:                 break;
1363:             }
1364:         }
1365:         // done transitioning the state
1366:     }
