803:     private static SerializedValue<OptionalFailure<Object>> serializeAccumulator(
804:             String name, OptionalFailure<Accumulator<?, ?>> accumulator) {
805:         try {
806:             if (accumulator.isFailure()) {
807:                 return new SerializedValue<>(
808:                         OptionalFailure.ofFailure(accumulator.getFailureCause()));
809:             }
810:             return new SerializedValue<>(
811:                     OptionalFailure.of(accumulator.getUnchecked().getLocalValue()));
812:         } catch (IOException ioe) {
813:             LOG.error("Could not serialize accumulator " + name + '.', ioe);
814:             try {
815:                 return new SerializedValue<>(OptionalFailure.ofFailure(ioe));
816:             } catch (IOException e) {
817:                 throw new RuntimeException(
818:                         "It should never happen that we cannot serialize the accumulator serialization exception.",
819:                         e);
820:             }
821:         }
822:     }
