1021:     @Override
1022:     public void cancel() {
1023: 
1024:         assertRunningInJobMasterMainThread();
1025: 
1026:         while (true) {
1027:             JobStatus current = state;
1028: 
1029:             if (current == JobStatus.RUNNING
1030:                     || current == JobStatus.CREATED
1031:                     || current == JobStatus.RESTARTING) {
1032:                 if (transitionState(current, JobStatus.CANCELLING)) {
1033:                     resetExecutionGraph(ExecutionJobVertex::cancelWithFuture)
1034:                             .whenComplete(
1035:                                     (Void value, Throwable throwable) -> {
1036:                                         if (throwable != null) {
1037:                                             transitionState(
1038:                                                     JobStatus.CANCELLING,
1039:                                                     JobStatus.FAILED,
1040:                                                     new FlinkException(
1041:                                                             "Could not cancel job "
1042:                                                                     + getJobName()
1043:                                                                     + " because not all execution job vertices could be cancelled.",
1044:                                                             throwable));
1045:                                         } else {
1046:                                             // cancellations may currently be overridden by failures
1047:                                             // which trigger restarts, so we need to pass a proper
1048:                                             // restart global version here
1049:                                             allVerticesInTerminalState();
1050:                                         }
1051:                                     });
1052: 
1053:                     return;
1054:                 }
1055:             }
1056:             // Executions are being canceled. Go into cancelling and wait for
1057:             // all vertices to be in their final state.
1058:             else if (current == JobStatus.FAILING) {
1059:                 if (transitionState(current, JobStatus.CANCELLING)) {
1060:                     return;
1061:                 }
1062:             } else {
1063:                 // no need to treat other states
1064:                 return;
1065:             }
1066:         }
1067:     }
