227:                             .setStateTransitionManagerFactory(stateTransitionManagerFactory)
228:                             .setRescaleOnFailedCheckpointCount(rescaleOnFailedCheckpointsCount)
229:                             .build(ctx);
230: 
231:             // do multiple rescale iterations to verify that subsequent failed checkpoints after a
232:             // rescale result in the expected behavior
233:             for (int rescaleIteration = 1; rescaleIteration <= 3; rescaleIteration++) {
234: 
235:                 // trigger an initial failed checkpoint event to show that the counting only starts
236:                 // with the subsequent change event
237:                 testInstance.onFailedCheckpoint();
238: 
239:                 // trigger change
240:                 testInstance.onNewResourceRequirements();
