242:                 for (int i = 0; i < rescaleOnFailedCheckpointsCount; i++) {
243:                     assertThat(rescaleTriggerCount)
244:                             .as(
245:                                     "No rescale operation should have been triggered for iteration #%d, yet.",
246:                                     rescaleIteration)
247:                             .hasValue(rescaleIteration - 1);
248:                     testInstance.onFailedCheckpoint();
249:                 }
250: 
251:                 assertThat(rescaleTriggerCount)
252:                         .as(
253:                                 "The rescale operation for iteration #%d should have been properly triggered.",
254:                                 rescaleIteration)
255:                         .hasValue(rescaleIteration);
256:             }
257:         }
258:     }
