260:     @Test
261:     public void testOnCompletedCheckpointResetsFailedCheckpointCount() throws Exception {
262:         final AtomicInteger rescaleTriggeredCount = new AtomicInteger();
263:         final Function<StateTransitionManager.Context, StateTransitionManager>
264:                 stateTransitionManagerFactory =
265:                         context ->
266:                                 TestingStateTransitionManager.withOnTriggerEventOnly(
267:                                         rescaleTriggeredCount::incrementAndGet);
268: 
269:         final int rescaleOnFailedCheckpointsCount = 3;
270:         try (MockExecutingContext ctx = new MockExecutingContext()) {
271:             final Executing testInstance =
272:                     new ExecutingStateBuilder()
273:                             .setStateTransitionManagerFactory(stateTransitionManagerFactory)
274:                             .setRescaleOnFailedCheckpointCount(rescaleOnFailedCheckpointsCount)
275:                             .build(ctx);
276: 
277:             // trigger an initial failed checkpoint event to show that the counting only starts with
278:             // the subsequent change event
279:             testInstance.onFailedCheckpoint();
280: 
281:             // trigger change
282:             testInstance.onNewResourcesAvailable();
283: 
284:             IntStream.range(0, rescaleOnFailedCheckpointsCount - 1)
285:                     .forEach(ignored -> testInstance.onFailedCheckpoint());
286: 
287:             assertThat(rescaleTriggeredCount)
288:                     .as("No rescaling should have been trigger, yet.")
289:                     .hasValue(0);
290: 
291:             testInstance.onCompletedCheckpoint();
292: 
293:             // trigger change
294:             testInstance.onNewResourceRequirements();
295: 
296:             assertThat(rescaleTriggeredCount)
297:                     .as("The completed checkpoint should have triggered a rescale.")
298:                     .hasValue(1);
299: 
300:             IntStream.range(0, rescaleOnFailedCheckpointsCount - 1)
301:                     .forEach(ignored -> testInstance.onFailedCheckpoint());
302: 
303:             assertThat(rescaleTriggeredCount)
304:                     .as(
305:                             "No additional rescaling should have been trigger by any subsequent failed checkpoint, yet.")
306:                     .hasValue(1);
307: 
308:             testInstance.onFailedCheckpoint();
309: 
310:             assertThat(rescaleTriggeredCount)
311:                     .as("The previous failed checkpoint should have triggered the rescale.")
312:                     .hasValue(2);
