214:     @Test
215:     public void testTriggerRescaleOnFailedCheckpoint() throws Exception {
216:         final AtomicInteger rescaleTriggerCount = new AtomicInteger();
217:         final Function<StateTransitionManager.Context, StateTransitionManager>
218:                 stateTransitionManagerFactory =
219:                         context ->
220:                                 TestingStateTransitionManager.withOnTriggerEventOnly(
221:                                         rescaleTriggerCount::incrementAndGet);
222: 
223:         final int rescaleOnFailedCheckpointsCount = 3;
224:         try (MockExecutingContext ctx = new MockExecutingContext()) {
225:             final Executing testInstance =
226:                     new ExecutingStateBuilder()
227:                             .setStateTransitionManagerFactory(stateTransitionManagerFactory)
228:                             .setRescaleOnFailedCheckpointCount(rescaleOnFailedCheckpointsCount)
229:                             .build(ctx);
230: 
231:             // do multiple rescale iterations to verify that subsequent failed checkpoints after a
232:             // rescale result in the expected behavior
233:             for (int rescaleIteration = 1; rescaleIteration <= 3; rescaleIteration++) {
234: 
235:                 // trigger an initial failed checkpoint event to show that the counting only starts
236:                 // with the subsequent change event
237:                 testInstance.onFailedCheckpoint();
238: 
239:                 // trigger change
240:                 testInstance.onNewResourceRequirements();
241: 
242:                 for (int i = 0; i < rescaleOnFailedCheckpointsCount; i++) {
243:                     assertThat(rescaleTriggerCount)
244:                             .as(
245:                                     "No rescale operation should have been triggered for iteration #%d, yet.",
246:                                     rescaleIteration)
247:                             .hasValue(rescaleIteration - 1);
248:                     testInstance.onFailedCheckpoint();
249:                 }
250: 
251:                 assertThat(rescaleTriggerCount)
252:                         .as(
253:                                 "The rescale operation for iteration #%d should have been properly triggered.",
254:                                 rescaleIteration)
255:                         .hasValue(rescaleIteration);
256:             }
257:         }
258:     }
