176:                         // TwoPhaseCommittingSink with a stateful writer and a committer and post
177:                         // commit topology
178:                         Preconditions.checkArgument(
179:                                 writer instanceof DefaultStatefulSinkWriter,
180:                                 "Please provide a DefaultStatefulSinkWriter instance");
181:                         return new TestStatefulSinkV2<>(
182:                                 (DefaultStatefulSinkWriter<InputT>) writer,
183:                                 COMMITTABLE_SERIALIZER_FACTORY,
184:                                 committer,
185:                                 compatibleStateNames);
186:                     } else {
187:                         // TwoPhaseCommittingSink with a stateless writer and a committer and post
188:                         // commit topology
189:                         Preconditions.checkArgument(
190:                                 writer instanceof DefaultCommittingSinkWriter,
191:                                 "Please provide a DefaultCommittingSinkWriter instance");
192:                         return new TestSinkV2WithPostCommitTopology<>(
193:                                 writer, COMMITTABLE_SERIALIZER_FACTORY, committer);
194:                     }
195:                 }
196:             }
197:         }
198:     }
