412:     // -------------------------------------- Sink Committer ---------------------------------------
413: 
414:     /** Base class for testing {@link Committer}. */
415:     public static class DefaultCommitter implements Committer<String>, Serializable {
416: 
417:         @Nullable protected Queue<CommitRequest<String>> committedData;
418: 
419:         private boolean isClosed;
420: 
421:         @Nullable private final Supplier<Queue<CommitRequest<String>>> queueSupplier;
422: 
423:         public DefaultCommitter() {
424:             this.committedData = new ConcurrentLinkedQueue<>();
425:             this.isClosed = false;
426:             this.queueSupplier = null;
427:         }
428: 
429:         public DefaultCommitter(@Nullable Supplier<Queue<CommitRequest<String>>> queueSupplier) {
430:             this.queueSupplier = queueSupplier;
431:             this.isClosed = false;
432:             this.committedData = null;
433:         }
434: 
435:         public List<CommitRequest<String>> getCommittedData() {
436:             if (committedData != null) {
437:                 return new ArrayList<>(committedData);
438:             } else {
439:                 return Collections.emptyList();
440:             }
441:         }
442: 
443:         @Override
444:         public void commit(Collection<CommitRequest<String>> committables) {
445:             if (committedData == null) {
446:                 assertThat(queueSupplier).isNotNull();
447:                 committedData = queueSupplier.get();
448:             }
449:             committedData.addAll(committables);
450:         }
451: 
452:         public void close() throws Exception {
453:             isClosed = true;
454:         }
455: 
456:         public boolean isClosed() {
457:             return isClosed;
458:         }
459: 
460:         public void init() {
461:             // context is not used for this implementation
462:         }
463:     }
464: 
465:     /** A {@link Committer} that always re-commits the committables data it received. */
466:     static class RetryOnceCommitter extends DefaultCommitter {
467: 
468:         private final Set<String> seen = new LinkedHashSet<>();
469: 
470:         @Override
471:         public void commit(Collection<CommitRequest<String>> committables) {
472:             committables.forEach(
473:                     c -> {
474:                         if (seen.remove(c.getCommittable())) {
475:                             checkNotNull(committedData);
476:                             committedData.add(c);
477:                         } else {
478:                             seen.add(c.getCommittable());
479:                             c.retryLater();
480:                         }
481:                     });
482:         }
483:     }
484: }
